import { useMemo } from 'react';

import {
  usePageFilterApplied,
  usePageFilterData,
  usePageFilterStatus,
} from 'hooks';

import { COMMERCIAL_RESULTS_PAGE_NAME } from '../../constants';

export interface DataView {
  loading: boolean;
  error: Error | null;
  isEmpty: boolean;
  skipped?: boolean;
}

export interface UseCommercialResultsFullPageEmptyStateResult {
  showFullPageEmpty: boolean;
  showFullPageError: boolean;
}

export const useCommercialResultsFullPageEmptyState = (
  views: DataView[],
): UseCommercialResultsFullPageEmptyStateResult => {
  const { applied } = usePageFilterApplied(COMMERCIAL_RESULTS_PAGE_NAME);
  const { status } = usePageFilterStatus(COMMERCIAL_RESULTS_PAGE_NAME);
  const { dataFilters } = usePageFilterData(COMMERCIAL_RESULTS_PAGE_NAME);

  const hasFilterOptions = dataFilters && Object.keys(dataFilters).length > 0;
  const hasRequiredAppliedFilters = !!applied?.zone && !!applied?.country;
  const shouldShowUnavailableMarketEmptyState =
    status === 'loaded' && (!hasFilterOptions || !hasRequiredAppliedFilters);

  const activeViews = useMemo(
    () => views.filter((view) => !view.skipped),
    [views],
  );

  const showFullPageError = useMemo(() => {
    if (activeViews.length === 0) return false;
    if (activeViews.some((view) => view.loading)) return false;
    return activeViews.every((view) => view.error);
  }, [activeViews]);

  const showFullPageEmpty = useMemo(() => {
    if (showFullPageError) return false;
    if (shouldShowUnavailableMarketEmptyState) return true;

    if (activeViews.length === 0) return false;
    if (activeViews.some((view) => view.error)) return false;
    if (!activeViews.some((view) => !view.loading)) return false;
    return activeViews.every((view) => view.isEmpty);
  }, [activeViews, shouldShowUnavailableMarketEmptyState, showFullPageError]);

  return { showFullPageEmpty, showFullPageError };
};
